"""Admission test and schedule compiler for recurring nonuniform allgather.

Model (PROTOCOL.md): participants may replicate chunks they already hold,
ordinary forwarding vertices may not replicate or aggregate.  One period gives
c_l = p * b_l chunk slots on every directed physical link.  A proposal is
admissible exactly when no vertex set S holding some but not all participants
is deficient:

    sum(c_l for links crossing S)  >=  sum(r_v for participants v in S)

which is the weighted multi-root arborescence packing condition (Edmonds) for
the participant graph obtained after reserving forwarding paths.  When some S
is deficient we return it as a checkable negative witness.  Otherwise we
compile weighted logical out-trees plus compressed physical unicast routes:

  phase 1  reserve forwarding paths between participants until the reserved
           logical capacity satisfies every participant cut (cutting plane);
  phase 2  pack weighted logical out-trees into the reserved capacity, growing
           one arc at a time and validating each step with an exact min-cut
           probe so the packing can always be finished;
  phase 3  expand reserved logical capacity into physical walks, aggregate
           per ordered participant pair and hash-cons the recipe circuit.
"""

from fcflow import FlowGraph

INF = 1 << 200


# --------------------------------------------------------------------------
# deficient cut search
# --------------------------------------------------------------------------
def deficient_cut(n, arcs, parts, rdem, total):
    """Return a vertex set S violating the cut condition, or None.

    arcs: dict (u,v)->capacity.  A violation is a set S with at least one but
    not all participants and arcs-out(S) < sum of demands inside S.
    """
    for b in parts:
        g = FlowGraph(n + 2)
        sig = n
        tau = n + 1
        for (u, v), c in arcs.items():
            if c > 0:
                g.add_arc(u, v, c)
        for w in parts:
            if rdem[w] > 0:
                g.add_arc(sig, w, rdem[w])
        g.add_arc(b, tau, INF)
        val, reach = g.maxflow(sig, tau, want_cut=True)
        if val < total:
            return [i for i in range(n) if reach[i]]
    return None


# --------------------------------------------------------------------------
# phase 1: reserve forwarding paths between participants
# --------------------------------------------------------------------------
class PathReserver:
    """Reserves physical walks between participants (cutting plane)."""

    def __init__(self, n, cap, parts, rdem, total):
        self.n = n
        self.cap = dict(cap)
        self.parts = sorted(parts)
        self.pset = set(parts)
        self.rdem = rdem
        self.total = total
        self.m = {}          # logical arc -> reserved capacity
        self.pool = {}       # logical arc -> list of [walk arcs, capacity]
        # participant to participant links are usable only by that logical arc
        for (u, v), c in self.cap.items():
            if c > 0 and u in self.pset and v in self.pset:
                self._add(u, v, [[(u, v)]], [c])
                self.cap[(u, v)] = 0

    def _add(self, a, b, walks, counts):
        key = (a, b)
        self.m[key] = self.m.get(key, 0) + sum(counts)
        pool = self.pool.setdefault(key, [])
        for w, c in zip(walks, counts):
            if c > 0:
                pool.append([w, c])

    def cut_deficiency(self, S):
        Sset = set(S)
        have = 0
        for (a, b), c in self.m.items():
            if a in Sset and b not in Sset:
                have += c
        need = 0
        for v in S:
            need += self.rdem[v]
        return need - have

    def _split_graph(self, S, limit):
        """Flow network where participants cannot be transited."""
        n = self.n
        parts = self.parts
        pset = self.pset
        inn = {}
        for i, w in enumerate(parts):
            inn[w] = n + i
        N = n + len(parts)
        sig = N
        tau = N + 1
        lim = N + 2
        g = FlowGraph(N + 3)
        for (u, v), c in self.cap.items():
            if c <= 0:
                continue
            a = u if u not in pset else u
            b = v if v not in pset else inn[v]
            g.add_arc(a, b, c)
        Sset = set(S)
        for w in parts:
            if w in Sset:
                g.add_arc(sig, w, INF)
            else:
                g.add_arc(inn[w], tau, INF)
        g.add_arc(lim, sig, limit)
        return g, lim, tau, inn

    def reserve(self, S, limit):
        """Push up to `limit` units from participants in S to the others."""
        g, lim, tau, inn = self._split_graph(S, limit)
        val, flows = g.maxflow_with_arcs(lim, tau)
        if val <= 0:
            return 0
        # collect flow on physical arcs
        fnet = {}
        for i, f in flows:
            u = g.to[i ^ 1]
            v = g.to[i]
            fnet[(u, v)] = fnet.get((u, v), 0) + f
        # strip the source/sink scaffolding
        out_of = {}
        into = {}
        rev_inn = {v: k for k, v in inn.items()}
        for (u, v), f in fnet.items():
            if u == lim or v == tau or u == tau or v == lim:
                continue
            out_of.setdefault(u, []).append([v, f])
            into.setdefault(v, []).append([u, f])
        # walk extraction: from each participant "out" node to a participant in
        walks = []
        counts = []
        Sset = set(S)
        starts = [w for w in self.parts if w in Sset]
        for st in starts:
            while True:
                lst = out_of.get(st)
                if not lst:
                    break
                # follow a path
                path = []
                cur = st
                ok = True
                while True:
                    lst = out_of.get(cur)
                    if not lst:
                        ok = False
                        break
                    nxt = None
                    for e in lst:
                        if e[1] > 0:
                            nxt = e
                            break
                    if nxt is None:
                        ok = False
                        break
                    nxt[1] -= 1 if False else 0
                    # take as much as possible along the whole walk later; here
                    # we walk one arc at a time recording unit structure
                    path.append((cur, nxt[0]))
                    amt = nxt[1]
                    nxt[1] = 0
                    cur = nxt[0]
                    if cur in rev_inn:
                        break
                    if cur == tau:
                        ok = False
                        break
                if not ok:
                    break
                if cur in rev_inn:
                    end = rev_inn[cur]
                    # amount is the minimum along the path (we consumed fully)
                    walks.append(path)
                    counts.append(1)
        return val

    def run(self, max_rounds=4000):
        parts = self.parts
        rdem = self.rdem
        total = self.total
        n = self.n
        for _ in range(max_rounds):
            S = deficient_cut(n, self.m, parts, rdem, total)
            if S is None:
                return True
            S = [v for v in S if v in self.pset]
            if not S:
                return False
            delta = self.cut_deficiency(S)
            if delta <= 0:
                return False
            got = self.push(S, delta)
            if got <= 0:
                return False
        return False

    def push(self, S, limit):
        g, lim, tau, inn = self._split_graph(S, limit)
        val, flows = g.maxflow_with_arcs(lim, tau)
        if val <= 0:
            return 0
        fnet = {}
        for i, f in flows:
            u = g.to[i ^ 1]
            v = g.to[i]
            fnet[(u, v)] = fnet.get((u, v), 0) + f
        rev_inn = {v: k for k, v in inn.items()}
        pset = self.pset
        # translate split-graph arcs back to physical arcs, drop scaffolding
        adj = {}
        for (u, v), f in fnet.items():
            if f <= 0:
                continue
            if u == lim or v == tau or u == tau or v == lim:
                continue
            adj.setdefault(u, []).append([v, f])
        walks = []
        counts = []
        Sset = set(S)
        for st in [w for w in parts if w in Sset]:
            while adj.get(st):
                # trace one walk, carrying the bottleneck amount
                path = []
                cur = st
                bottleneck = None
                while True:
                    lst = adj.get(cur)
                    if not lst:
                        break
                    e = None
                    for cand in lst:
                        if cand[1] > 0:
                            e = cand
                            break
                    if e is None:
                        break
                    path.append((cur, e[0]))
                    if bottleneck is None or e[1] < bottleneck:
                        bottleneck = e[1]
                    cur = e[0]
                    if cur in rev_inn:
                        break
                if not path or cur not in rev_inn:
                    break
                amt = bottleneck
                # consume amt along the walk
                for (a, b) in path:
                    lst = adj[a]
                    for e in lst:
                        if e[0] == b and e[1] > 0:
                            take = amt if amt < e[1] else e[1]
                            e[1] -= take
                            break
                phys = []
                for (a, b) in path:
                    pa = rev_inn[a] if a in rev_inn else a
                    pb = rev_inn[b] if b in rev_inn else b
                    phys.append((pa, pb))
                walks.append(phys)
                counts.append(amt)
        if not walks:
            return 0
        # bookkeeping: consume residual capacity, record reservations
        for w, c in zip(walks, counts):
            for (a, b) in w:
                self.cap[(a, b)] = self.cap.get((a, b), 0) - c
                if self.cap[(a, b)] < 0:
                    raise RuntimeError('over-reserved %r' % ((a, b),))
        # group by logical pair
        bypair = {}
        for w, c in zip(walks, counts):
            key = (w[0][0], w[-1][1])
            bypair.setdefault(key, []).append((w, c))
        for (a, b), lst in bypair.items():
            merged = {}
            order = []
            for w, c in lst:
                k = tuple(w)
                if k not in merged:
                    merged[k] = 0
                    order.append(k)
                merged[k] += c
            self._add(a, b, [list(k) for k in order], [merged[k] for k in order])
        return val


# --------------------------------------------------------------------------
# phase 2: weighted branching packing over reserved logical capacity
# --------------------------------------------------------------------------
class BranchingPacker:
    def __init__(self, parts, rcap, rdem):
        self.parts = sorted(parts)
        self.idx = {v: i for i, v in enumerate(self.parts)}
        self.n = len(self.parts)
        self.rcap = {}
        for k, v in rcap.items():
            if v > 0:
                self.rcap[k] = v
        self.rdem = dict(rdem)
        self.out = {}
        for (a, b) in self.rcap:
            self.out.setdefault(a, []).append(b)
        self.fg = FlowGraph(self.n)
        self.arc_of = {}
        for (a, b), c in self.rcap.items():
            self.arc_of[(a, b)] = self.fg.add_arc(self.idx[a], self.idx[b], c)
        self.single_arc = {}
        for x in self.parts:
            for u in self.parts:
                if x != u:
                    self.single_arc[(x, u)] = self.fg.add_arc(self.idx[x],
                                                              self.idx[u], 0)
        self.trees = {}
        self.next_tid = 0
        self.temp_arcs = {}
        self.single = {}
        for v in self.parts:
            if self.rdem.get(v, 0) > 0:
                self._new_tree(v, self.rdem[v], {v}, [])

    def _new_tree(self, root, w, R, edges):
        tid = self.next_tid
        self.next_tid += 1
        snode = None
        if len(R) > 1:
            snode = self.fg.add_node()
            for v in R:
                self.fg.add_arc(snode, self.idx[v], INF)
        self.trees[tid] = {'root': root, 'w': w, 'R': set(R),
                           'edges': list(edges), 'snode': snode}
        if snode is None:
            self.single[root] = self.single.get(root, 0) + w
        return tid

    def _drop_tree(self, tid):
        T = self.trees[tid]
        if T['snode'] is None:
            self.single[T['root']] -= T['w']
        else:
            sn = T['snode']
            for i in list(self.fg.adj[sn]):
                self.fg.set_cap(i, 0)
            for x in self.parts:
                a = self.temp_arcs.get((x, tid))
                if a is not None:
                    self.fg.set_cap(a, 0)
        del self.trees[tid]

    def _temp_arc(self, x, tid):
        a = self.temp_arcs.get((x, tid))
        if a is None:
            T = self.trees[tid]
            a = self.fg.add_arc(self.idx[x], T['snode'], 0)
            self.temp_arcs[(x, tid)] = a
        return a

    def test_edge(self, tid, x, y):
        T = self.trees[tid]
        cap_xy = self.rcap.get((x, y), 0)
        if cap_xy <= 0:
            return 0
        fg = self.fg
        c_sum = 0
        touched = []
        for u, w in self.single.items():
            if w <= 0:
                continue
            if T['snode'] is None and T['root'] == u:
                w -= T['w']
                if w <= 0:
                    continue
            a = self.single_arc.get((x, u))
            if a is None:
                continue
            fg.set_cap(a, w)
            touched.append(a)
            c_sum += w
        for oid, O in self.trees.items():
            if oid == tid or O['snode'] is None:
                continue
            a = self._temp_arc(x, oid)
            fg.set_cap(a, O['w'])
            touched.append(a)
            c_sum += O['w']
        val = fg.maxflow(self.idx[x], self.idx[y])
        for a in touched:
            fg.set_cap(a, 0)
        chunks = val - c_sum
        if chunks > T['w']:
            chunks = T['w']
        if chunks > cap_xy:
            chunks = cap_xy
        return chunks if chunks > 0 else 0

    def generate(self):
        parts = self.parts
        nparts = len(parts)
        queue = sorted(self.trees.keys())
        done = []
        guard = 0
        while queue:
            guard += 1
            if guard > 100000:
                raise RuntimeError('branching packer did not converge')
            tid = queue.pop(0)
            T = self.trees.get(tid)
            if T is None:
                continue
            bfs = list(T['R'])
            head = 0
            while head < len(bfs):
                x = bfs[head]
                head += 1
                cands = [(b, self.rcap.get((x, b), 0)) for b in self.out.get(x, ())
                         if b not in T['R'] and self.rcap.get((x, b), 0) > 0]
                cands.sort(key=lambda e: (-e[1], e[0]))
                for y, _c in cands:
                    if y in T['R']:
                        continue
                    if self.rcap.get((x, y), 0) <= 0:
                        continue
                    chunks = self.test_edge(tid, x, y)
                    if chunks <= 0:
                        continue
                    bfs.append(y)
                    if chunks < T['w']:
                        ntid = self._new_tree(T['root'], T['w'] - chunks,
                                              T['R'], T['edges'])
                        queue.append(ntid)
                        if T['snode'] is None:
                            self.single[T['root']] -= T['w']
                        T['w'] = chunks
                        if T['snode'] is None:
                            self.single[T['root']] += chunks
                    T['edges'].append((x, y))
                    T['R'].add(y)
                    if T['snode'] is not None:
                        self.fg.add_arc(T['snode'], self.idx[y], INF)
                    a = self.arc_of.get((x, y))
                    self.rcap[(x, y)] -= chunks
                    if a is not None:
                        self.fg.set_cap(a, self.rcap[(x, y)])
                    if self.rcap[(x, y)] <= 0:
                        del self.rcap[(x, y)]
            if len(T['R']) != nparts:
                raise RuntimeError('branching incomplete for root %r' % (T['root'],))
            done.append((T['root'], T['w'], list(T['edges'])))
            self._drop_tree(tid)
        return done


# --------------------------------------------------------------------------
# phase 3: recipes and plan emission
# --------------------------------------------------------------------------
class RecipeBuilder:
    def __init__(self, link_of):
        self.nodes = []
        self.leaf = {}
        self.cat = {}
        self.link_of = link_of

    def leaf_id(self, uv):
        lid = self.leaf.get(uv)
        if lid is None:
            l, d = self.link_of[uv]
            lid = len(self.nodes)
            self.nodes.append([0, l, d])
            self.leaf[uv] = lid
        return lid

    def cat_id(self, a, b):
        k = (a, b)
        lid = self.cat.get(k)
        if lid is None:
            lid = len(self.nodes)
            self.nodes.append([1, a, b])
            self.cat[k] = lid
        return lid

    def path_id(self, arcs):
        cur = None
        for uv in arcs:
            lid = self.leaf_id(uv)
            cur = lid if cur is None else self.cat_id(cur, lid)
        return cur


def compile_plan(n, links, link_caps, parts, rdem):
    """Return ('cut', S) with a deficient witness or ('plan', PLAN)."""
    link_of = {}
    cap = {}
    for lid, (u, v) in enumerate(links):
        if u == v:
            continue
        c = link_caps[lid]
        if c <= 0:
            continue
        link_of[(u, v)] = (lid, 0)
        link_of[(v, u)] = (lid, 1)
        cap[(u, v)] = cap.get((u, v), 0) + c
        cap[(v, u)] = cap.get((v, u), 0) + c
    parts = sorted(parts)
    total = 0
    for v in parts:
        total += rdem[v]
    if total <= 0:
        raise RuntimeError('no demand')
    cut = deficient_cut(n, cap, parts, rdem, total)
    if cut is not None:
        return ('cut', cut)
    res = PathReserver(n, cap, parts, rdem, total)
    if not res.run():
        raise RuntimeError('path reservation failed')
    trees = BranchingPacker(parts, res.m, rdem).generate()
    load = {}
    for root, w, edges in trees:
        for e in edges:
            load[e] = load.get(e, 0) + w
    rb = RecipeBuilder(link_of)
    routes = []
    for (a, b), need in sorted(load.items()):
        left = need
        for walk, avail in res.pool.get((a, b), ()):
            if left <= 0:
                break
            take = avail if avail < left else left
            if take <= 0:
                continue
            left -= take
            routes.append([a, b, take, rb.path_id(walk)])
        if left != 0:
            raise RuntimeError('route shortfall for %r' % ((a, b),))
    out_trees = [[root, w, [[a, b] for (a, b) in edges]]
                 for root, w, edges in trees]
    return ('plan', {'trees': out_trees, 'routes': routes,
                     'recipes': rb.nodes})
